event.script:
var reg = new RegExp("^([\\w]|[\\s]|[-]|[.])+$");
if(!reg.test(xfa.event.change))
{
xfa.event.change = "";
}

if(this.access == "open") {
   try{
   if(this.rawValue != null){
	   this.rawValue = this.rawValue.replace(/^\s+|\s+$/gm,'');	
	   var validCNP = cnp.validcnp(this.rawValue);	
	   if(validCNP  == false){
		   xfa.host.messageBox("Codul de indetificare fiscala nu este valid","DOCUMENT DE FUNDAMENTARE");
		   xfa.host.setFocus(this);}
	   }	
}catch(e){
  xfa.host.messageBox(e.name+""+e.message);
}
}

if(this.access == "open") {
   try {
      if(this.rawValue != null){ 
         if(this.rawValue.length !=10 ){xfa.host.setFocus(this); xfa.host.messageBox("Lungime data incorecta " + this.rawValue.length +  " !!!");}
         var van=""; 
         var vluna="";
         var vzi="";
         if(!(this.rawValue.indexOf("-") == -1)) { // am completat cu calendarul si data.rawValue e de forma yyyy-mm-dd   
           van = this.rawValue.substring(0,4) ;
           vluna = this.rawValue.substring(5,7) ;
           vzi = this.rawValue.substring(8) ; 
         }else { if(!(this.rawValue.indexOf(".") == -1)) { // am completat de mana cu . data e de forma zz.mm.yyyy 
                                                          van = this.rawValue.substring(6,10) ;
                                                          vluna  = this.rawValue.substring(3,5) ;
                                                          vzi = this.rawValue.substring(0,2) ;
                                                         } else {xfa.host.setFocus(this); xfa.host.messageBox("Data incorecta!!!"); }      
               }
                //xfa.host.messageBox(vzi + "." + vluna + "." + van );
		        var regd = new RegExp("^([0-9]*)$");
                var rvan = regd.test(van);
                var rvluna = regd.test(vluna);
                var rvzi = regd.test(vzi);

                //if(!reg.test(xfa.event.newText))

		        if (vluna > 12 || vzi > 31 || van < 2020 || van > 2100 || !rvan || !rvluna || !rvzi ) {xfa.host.setFocus(this); xfa.host.messageBox("Data incorecta!!! " + " vzi" +  vzi + "." + vluna + "." + van );}  
	   }   
   }catch(e){
     xfa.host.messageBox(e.name+""+e.message);
     console.show();  }
}

var reg = new RegExp("^([0-9]*)$");
if(!reg.test(xfa.event.newText))
{
xfa.event.change = "";
}

var reg = new RegExp("^([\\w]|[\\s]|[-]|[.])+$");
if(!reg.test(xfa.event.change))
{
xfa.event.change = "";
}

var count= 0;
var oDoc = event.target;
var oAttachment = oDoc.dataObjects;
if(oAttachment != null){

count = oAttachment.length;

}
oDoc.importDataObject("attachment" + (count + 1))
var dataObj = oDoc.getDataObject("attachment" + (count + 1));

var fileName = dataObj.path;
var fileType = fileName.substring(fileName.lastIndexOf("."));
if(fileType != ".bmp" && fileType != ".BMP" && fileType != ".pdf" && fileType != ".PDF" && fileType != ".JPG" &&
fileType != ".jpg" && fileType != ".tif" && fileType != ".TIF"&&
fileType != ".tiff" && fileType != ".TIFF" &&
fileType != ".txt" && fileType != ".TXT" &&
fileType != ".doc" && fileType != ".DOC"){
xfa.host.messageBox("Selecteaza un tip acceptat de fisiere(bmp, pdf, jpg, tiff, doc, txt) !");
oDoc.removeDataObject("attachment" + (count + 1));

}

if( this.rawValue == 1) {   this.parent.parent.Table1.access = "open";
                            this.parent.parent.Subform423.access = "readOnly";
                            this.parent.parent.Subform423.sumRamasaFD.rawValue = "";
}else {//this.parent.Subform523.presence = "";   
       this.parent.parent.Subform423.access = "open";
       this.parent.parent.Table1.access = "readOnly";    
      }

if(this.rawValue != null){
   this.rawValue = this.rawValue.toUpperCase();
   //xfa.host.messageBox(" " + this.rawValue.length);
   if( this.rawValue.length != 10) {
      xfa.host.messageBox("Campul Program trebuie sa aiba lungimea de 10 caractere"); xfa.host.setFocus(this);
   }else { var gasitProgram = csGlobals.Data().validProgram(this.rawValue.toUpperCase());
           if(!gasitProgram) {xfa.host.messageBox("Campul Program nu exista in nomenclator"); xfa.host.setFocus(this);}
         }

}

//try {
if(this.rawValue != null){
   this.rawValue = this.rawValue.toUpperCase();
   //xfa.host.messageBox(" " + this.rawValue.length);
   if( this.rawValue.length != 15) {
      xfa.host.messageBox("Campul Cod SSI trebuie sa aiba lungimea de 15 caractere"); xfa.host.setFocus(this);
   }
//verific structura Cod SSI, sector 2 car numerice 01->05, sursa 1 car nenumeric, indicator 12 car numerice
var sec_SSI = this.rawValue.substring(0,2);
var suc_SSI = this.rawValue.substring(2,3);
var iic_SSI = this.rawValue.substring(3);
//xfa.host.messageBox(sec_SSI + "  " + suc_SSI + "  " + iic_SSI ); 					  
var TheErrMsgBT = "";
if( !(sec_SSI == "01" ||sec_SSI == "02" ||sec_SSI == "03" ||sec_SSI == "04" ||sec_SSI == "05")  ) {
     TheErrMsgBT += "Primele doua caractere din Cod SSI (cod sector) trebuie sa fie in intervalul 01-05  " + "\r\n";
}
if( !isNaN(suc_SSI) ) {
     TheErrMsgBT += "Al treilea caracter din Cod SSI (cod sursa) , trebuie sa fie nenumeric " + "\r\n";
}					  
if(!csGlobals.Data().validSursa(suc_SSI)) {TheErrMsgBT += "Al treilea caracter din Cod SSI (cod sursa) , nu se gaseste in nomenclator " + "\r\n";}

var regiiC = new RegExp("^([0-9]*)$");
var rviiC = regiiC.test(iic_SSI);
if(!rviiC){
     TheErrMsgBT += "Ultimele 12 caractere din Cod SSI (cod COFOG3) , trebuie sa fie numerice " + "\r\n";
}                      					  

if(!(Cell2.rawValue.toUpperCase()=="0000000000")){
   gasitProgramSector = csGlobals.Data().validProgramSector(Cell2.rawValue.toUpperCase(), sec_SSI);
   if(!gasitProgramSector) {TheErrMsgBT += "Campul Program " + Cell2.rawValue.toUpperCase()+   " nu exista in nomenclator pentru acest sector bugetar " + sec_SSI  + "\r\n";}
}       
if(TheErrMsgBT !="") { xfa.host.messageBox(TheErrMsgBT); xfa.host.setFocus(this); }

}


//}catch(e){
//  xfa.host.messageBox(e.name+""+e.message);
//  console.show();
//}

var optiuni = xfa.host.messageBox("Stergeti randul din tabel? ","STERGERE RAND",2,2);
if(optiuni==4) {  
try {
   var rdcrt = this.parent.index;
   //xfa.host.messageBox("TheInstanceCount this.parent.index  "  + this.parent.index + "  " + this.rawValue);
   var sumCell5  = 0; var sumCell6  = 0;
   var TheInstanceCount =  this.parent.parent._Row1.count;
   //xfa.host.messageBox("TheInstanceCount this.parent.index sumCell5 " + TheInstanceCount + "  " + this.parent.index + "  " + sumCell5 );
   var TheRow = this.parent.parent.Row1.all;
   for(i = 1; i<TheInstanceCount; i++) {
      if(rdcrt == i) {
          //sumCell5 = sumCell5 - TheRow.item(i).Cell5.rawValue ;
          }
      else {
          sumCell5 += TheRow.item(i).Cell5.rawValue ;
          sumCell6 += TheRow.item(i).Cell6.rawValue ;}
          //xfa.host.messageBox("i sumCell5  valrow " + i + "  " + sumCell5 + "  " + TheRow.item(i).Cell5.rawValue);
   }
   this.parent.parent.FooterRow.Cell5.rawValue = sumCell5;
   this.parent.parent.FooterRow.Cell6.rawValue = sumCell6;
}catch(e){
  xfa.host.messageBox(e.name+""+e.message);
  console.show();
}

 this.parent.parent.Row1.instanceManager.removeInstance(this.parent.index );


}

