FData.validAntetSectiuneaA = function(){
    var TheErrMsg = "";
    //validare antet

    if(FData.SubformAntet.DenInstPb.rawValue == null || FData.SubformAntet.DenInstPb.rawValue =="") {TheErrMsg += "Denumirea institutiei publice trebuie completata" + "\r\n";}

    if(FData.SubformAntet.cif.rawValue == null || FData.SubformAntet.cif.rawValue =="") {TheErrMsg += "Cod de identificare fiscala trebuie completat"  + "\r\n";}
    else { if(!cnp.validcnp(FData.SubformAntet.cif.rawValue)	) {TheErrMsg += "Codul de indetificare fiscala nu este valid "  + "\r\n";}
         }

    //if(FData.SubformAntet.NrUnicInreg.rawValue == null || FData.SubformAntet.NrUnicInreg.rawValue =="") {TheErrMsg += "Numarul unic de inregistrare trebuie completat" + "\r\n";}     

    if(FData.SubformAntet.Revizuirea.rawValue == null || FData.SubformAntet.Revizuirea.rawValue =="") {TheErrMsg += "Campul Revizuirea trebuie completat" + "\r\n";}     

    if(FData.SubformAntet.DataRevizuirii.rawValue == null || FData.SubformAntet.DataRevizuirii.rawValue =="") {TheErrMsg += "Data Revizuirii trebuie completata" + "\r\n";}     
    TheErrMsg +=  csGlobals.Data().validData(FData.SubformAntet.DataRevizuirii);

    // validare sectiunea A 
    if(csGlobals.Data().Subform123.ComparimentSpecialitate.rawValue == null ||  csGlobals.Data().Subform123.ComparimentSpecialitate.rawValue == ""   ) {
           TheErrMsg += "Campul Compartiment de specialitate necompletat!!! " + "\r\n";
    }
    if(csGlobals.Data().Subform123.DescrieObFundRevizuireScurt.rawValue == null ||  csGlobals.Data().Subform123.DescrieObFundRevizuireScurt.rawValue == ""   ) {
           TheErrMsg += "Descrierea pe scurt a obiectului documentului de fundamentare necompletata!!! " + "\r\n";
    }
   if(csGlobals.Data().Subform123.DescrieObFundRevizuireLung.rawValue == null ||  csGlobals.Data().Subform123.DescrieObFundRevizuireLung.rawValue == ""   ) {
       TheErrMsg += "Descrierea pe larg a starii de fapt si de drept necompletata!!! " + "\r\n";
    }

   if(csGlobals.Data().CheckBox2.rawValue == 0  && csGlobals.Data().CheckBox3.rawValue == 0 ) {
      TheErrMsg += "Nu ati selectat una dintre optiunile de la punctul 4 sectiunea A " + "\r\n";
   }
   if(csGlobals.Data().CheckBox2.rawValue == 1  && csGlobals.Data().CheckBox3.rawValue == 1 ) {
      TheErrMsg += "Ati selectat ambele optiunile de la punctul 4 sectiunea A, lucru nepermis " + "\r\n";
   }

   if(csGlobals.Data().CheckBox2.rawValue == 1  && csGlobals.Data().TableFD._Row1.count ==1 ) {
      TheErrMsg += "Nu ati completat tabelul cu angajamentele legale de la punctul 4 Sectiunea A " + "\r\n";
   }
   if(csGlobals.Data().CheckBox2.rawValue == 0  && csGlobals.Data().TableFD._Row1.count> 1 ) {
      TheErrMsg += "Aveti randuri in  tabelul cu angajamentele legale de la punctul 4 Sectiunea A, dar nu ati bifat optiunea de completare a tabelului  " + "\r\n";
   }
   //xfa.host.messageBox("01"); 
   if(csGlobals.Data().CheckBox2.rawValue == 1  && csGlobals.Data().TableFD._Row1.count >1 ) {
      // verific ca tabelul de fundamentare sa fie completat corect
      var TheRow = "";
         //xfa.host.messageBox("011"); 
         for(i1 = 1; i1<csGlobals.Data().TableFD._Row1.count; i1++){
            //xfa.host.messageBox("i1 < csGlobals.Data().TableFD._Row1.count " + i1 + " < " + csGlobals.Data().TableFD._Row1.count);
            TheRow = csGlobals.Data().TableFD.Row1.all.item(i1);
            if(TheRow.Cell1.rawValue == null || TheRow.Cell1.rawValue == "" ) {
               TheErrMsg += "Nu ati completat coloana ,Element de fundamentare, randul " + i1+ " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A " + "\r\n";
            }
            //program
            if(TheRow.Cell2.rawValue == null || TheRow.Cell2.rawValue == "" ) {
               TheErrMsg += "Nu ati completat coloana ,Program, randul " + i1+ " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A " + "\r\n";}
            else {if(TheRow.Cell2.rawValue.length !=10 ) {TheErrMsg += "Coloana ,Program, randul " + i1 + " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A, nu are 10 caractere "  + TheRow.Cell2.rawValue.length + " " +   "\r\n"; }
                  else { //verific sa am numai caractere numerice in cod program
                         var regp = new RegExp("^([0-9]*)$");
                         var rvprg = regp.test(TheRow.Cell2.rawValue);
                         if(!rvprg){TheErrMsg += "Coloana ,Program, randul " + i1 + " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A, trebuie sa aiba numai caractere numerice " + "\r\n";}

                       }   
                 }
      //xfa.host.messageBox("012"); 

         //cod SSI
         if(TheRow.Cell3.rawValue == null || TheRow.Cell3.rawValue == "" ) {
               TheErrMsg += "Nu ati completat coloana ,Cod SSI, randul " + i1+ " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A " + "\r\n";}
            else {if(TheRow.Cell3.rawValue.length !=15 ) {TheErrMsg += "Coloana ,Cod SSI, randul " + i1 + " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A, nu are 15 caractere "  + TheRow.Cell3.rawValue.length + " " +   "\r\n"; }
                  else { //verific structura Cod SSI, sector 2 car numerice 01->05, sursa 1 car nenumeric, indicator 12 car numerice
                         //xfa.host.messageBox("0121"); 
				    	  var se_SSI = TheRow.Cell3.rawValue.substring(0,2);
                         var su_SSI = TheRow.Cell3.rawValue.substring(2,3);
                         var ii_SSI = TheRow.Cell3.rawValue.substring(3);
                         ////xfa.host.messageBox(se_SSI + "  " + su_SSI + "  " + ii_SSI ); 					  
					     if( !(se_SSI == "01" ||se_SSI == "02" ||se_SSI == "03" ||se_SSI == "04" ||se_SSI == "05")  ) {
					        TheErrMsg += "Primele doua caractere din Cod SSI (cod sector) , randul " + i1+ " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A, trebuie sa fie in intervalul 01-05  " + "\r\n";
					     }
					     if( !isNaN(su_SSI) ) {
					        TheErrMsg += "Al treilea caracter din Cod SSI (cod sursa) , randul " + i1+ " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A, trebuie sa fie nenumeric " + "\r\n";
					     }					  
                         //xfa.host.messageBox("0122"); 
					     if(!csGlobals.Data().validSursa(su_SSI)) {TheErrMsg  += "Al treilea caracter din Cod SSI (cod sursa) , nu se gaseste in nomenclator, randul " + i1 + " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A " + "\r\n";}

					     var regii = new RegExp("^([0-9]*)$");
                         var rvii = regii.test(ii_SSI);
                         if(!rvii){TheErrMsg += "Ultimele 12 caractere din Cod SSI (cod COFOG3) , randul " + i1+ " din tabelul cu angajamentele legale de la punctul 4 Sectiunea A, trebuie sa fie numerice " + "\r\n";}                      					  
                         ////xfa.host.messageBox("10"); 
                         //xfa.host.messageBox("0123"); 
                         if(!(TheRow.Cell2.rawValue.toUpperCase()=="0000000000")){
                             ////xfa.host.messageBox("11"); 
                             //xfa.host.messageBox("0124"); 
						     var gasitProgramSector = csGlobals.Data().validProgramSector(TheRow.Cell2.rawValue.toUpperCase(), se_SSI);
                             //xfa.host.messageBox("0125"); 
                             ////xfa.host.messageBox("12"); 
                             if(!gasitProgramSector) {TheErrMsg += "Campul Program " + TheRow.Cell2.rawValue.toUpperCase()+   " nu exista in nomenclator pentru acest sector bugetar " + se_SSI  + " randul " + i1 + "\r\n";}
                             ////xfa.host.messageBox("13"); 
                         }       
                 }
              } 
         } //endfor

//xfa.host.messageBox("013"); 

      //TheErrMsg += "Nu ati completat tabelul cu angajamentele legale de la punctul 4 Sectiunea A " + "\r\n";
   }

   if(csGlobals.Data().CheckBox3.rawValue == 1  && (csGlobals.Data().Subform423.sumRamasaFD.rawValue ==0 || csGlobals.Data().Subform423.sumRamasaFD.rawValue == null)  ) {
      TheErrMsg += "Ati bifat optiunea a doua de la punctul 4 sectiunea A, dar nu ati completat suma ramasa " + "\r\n";
   }

   // 5.Angajamente legale
   if(csGlobals.Data().CheckBox4.rawValue == 0  && csGlobals.Data().CheckBox5.rawValue == 0   && csGlobals.Data().CheckBox13.rawValue == 0 ) {
      TheErrMsg += "Nu ati selectat una dintre optiunile de la punctul 5 sectiunea A " + "\r\n";
   }
   if(csGlobals.Data().CheckBox4.rawValue == 1  && csGlobals.Data().CheckBox5.rawValue == 1 ) {
      TheErrMsg += "Ati selectat ambele optiunile de la punctul 5 sectiunea A, lucru nepermis " + "\r\n";
   }   
   if(csGlobals.Data().CheckBox5.rawValue == 1 && csGlobals.Data().CheckBox6.rawValue == 0 &&  csGlobals.Data().CheckBox7.rawValue == 0 &&  csGlobals.Data().CheckBox8.rawValue == 0 ) {
      TheErrMsg += "Nu ati selectat o suboptiune  a optiunii bifate la punctul 5 sectiunea A, lucru nepermis " + "\r\n";
   }   
   if((csGlobals.Data().CheckBox7.rawValue == 1  || csGlobals.Data().CheckBox8.rawValue == 1) && csGlobals.Data().TableANG._Row1.count ==1 ) {
      TheErrMsg += "Nu aveti randuri in tabelul de la punctul 5 sectiunea A, pentru selectiile bifate la punctul 5 sectiunea A " + "\r\n";
   }
   if((csGlobals.Data().CheckBox7.rawValue == 1  || csGlobals.Data().CheckBox8.rawValue == 1) && csGlobals.Data().TableANG._Row1.count >1 ) {
      // testez daca s-au completat corect randurile in tabelul de la pct 5 sectiunea A
      var TheRowA = "";
      for(i2 = 1; i2<csGlobals.Data().TableANG._Row1.count; i2++){      
         TheRowA = csGlobals.Data().TableANG.Row1.all.item(i2);      
         if(!((TheRowA.Cell1.rawValue != null && TheRowA.Cell1.rawValue != 0) || 
            (TheRowA.Cell2.rawValue != null && TheRowA.Cell2.rawValue != 0) ||
            (TheRowA.Cell3.rawValue != null && TheRowA.Cell3.rawValue != 0) ||
            (TheRowA.Cell4.rawValue != null && TheRowA.Cell4.rawValue != 0) ||
            (TheRowA.Cell5.rawValue != null && TheRowA.Cell5.rawValue != 0) ||
            (TheRowA.Cell6.rawValue != null && TheRowA.Cell6.rawValue != 0)) 
         ) { TheErrMsg += "Completati cel putin o coloana in tabelul de la punctul 5 sectiunea A, pentru selectiile bifate la punctul 5 sectiunea A " + "\r\n";
           }
         //program
         if(TheRowA.Cell7.rawValue == null || TheRowA.Cell7.rawValue == "" ) {
            TheErrMsg += "Nu ati completat coloana ,Program, randul " + i2+ " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A " + "\r\n";}
         else {if(TheRowA.Cell7.rawValue.length !=10 ) {TheErrMsg += "Coloana ,Program, randul " + i2 + " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A, nu are 10 caractere "  + TheRowA.Cell7.rawValue.length + " " +   "\r\n"; }
               else { //verific sa am numai caractere numerice in cod program
                      var regp = new RegExp("^([0-9]*)$");
                      var rvprg = regp.test(TheRowA.Cell7.rawValue);
                      if(!rvprg){TheErrMsg += "Coloana ,Program, randul " + i2 + " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A, trebuie sa aiba numai caractere numerice " + "\r\n";}

                    }   
              }

      //cod SSI
      if(TheRowA.Cell8.rawValue == null || TheRowA.Cell8.rawValue == "" ) {
            TheErrMsg += "Nu ati completat coloana ,Cod SSI, randul " + i2+ " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A " + "\r\n";}
         else {if(TheRowA.Cell8.rawValue.length !=15 ) {TheErrMsg += "Coloana ,Cod SSI, randul " + i2 + " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A, nu are 15 caractere "  + TheRowA.Cell8.rawValue.length + " " +   "\r\n"; }
               else { //verific structura Cod SSI, sector 2 car numerice 01->05, sursa 1 car nenumeric, indicator 12 car numerice
                      var se_SSI = TheRowA.Cell8.rawValue.substring(0,2);
                      var su_SSI = TheRowA.Cell8.rawValue.substring(2,3);
                      var ii_SSI = TheRowA.Cell8.rawValue.substring(3);
                      ////xfa.host.messageBox(se_SSI + "  " + su_SSI + "  " + ii_SSI ); 					  
					  if( !(se_SSI == "01" ||se_SSI == "02" ||se_SSI == "03" ||se_SSI == "04" ||se_SSI == "05")  ) {
					     TheErrMsg += "Primele doua caractere din Cod SSI (cod sector) , randul " + i2+ " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A, trebuie sa fie in intervalul 01-05  " + "\r\n";
					  }
					  if( !isNaN(su_SSI) ) {
					     TheErrMsg += "Al treilea caracter din Cod SSI (cod sursa) , randul " + i2+ " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A, trebuie sa fie nenumeric " + "\r\n";
					  }					  
                      if(!csGlobals.Data().validSursa(su_SSI)) {TheErrMsg  += "Al treilea caracter din Cod SSI (cod sursa) , nu se gaseste in nomenclator, randul " + i2 + " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A " + "\r\n";}

					  var regii = new RegExp("^([0-9]*)$");
                      var rvii = regii.test(ii_SSI);
                      if(!rvii){TheErrMsg += "Ultimele 12 caractere din Cod SSI (cod COFOG3) , randul " + i2+ " din tabelul cu angajamentele legale de la punctul 5 Sectiunea A, trebuie sa fie numerice " + "\r\n";}                      					  

                      if(!(TheRowA.Cell7.rawValue.toUpperCase()=="0000000000")){
                          var gasitProgramSector = csGlobals.Data().validProgramSector(TheRowA.Cell7.rawValue.toUpperCase(), se_SSI);
                          if(!gasitProgramSector) {TheErrMsg += "Campul Program " + TheRowA.Cell7.rawValue.toUpperCase()+   " nu exista in nomenclator pentru acest sector bugetar " + se_SSI + " randul " + i2 + "\r\n";}
                      }       


              }
           } 

      }
   }


if(TheErrMsg != "" ) { 
   xfa.host.messageBox(TheErrMsg);
} else {
  // compar totalurile in tabelele de la pct 4/5

   if((csGlobals.Data().CheckBox4.rawValue == 1 || (csGlobals.Data().CheckBox5.rawValue == 1 && csGlobals.Data().CheckBox6.rawValue == 1  ))  && 
       csGlobals.Data().TableFD._Row1.count> 1 ) {TheErrMsg += "";}
   else   { if((csGlobals.Data().CheckBox3.rawValue == 1 ||  
               csGlobals.Data().CheckBox5.rawValue == 1) && 
		      (csGlobals.Data().CheckBox7.rawValue == 1 || csGlobals.Data().CheckBox8.rawValue == 1  )) {
                  TheErrMsg += csGlobals.Data().comparTable1Table2();}

          }

  if(TheErrMsg != "" ) { xfa.host.messageBox(TheErrMsg); }
  else {xfa.host.messageBox("Nu sunt erori la sectiunea A");}

}

return TheErrMsg;

}

FData.comparTable1Table2 = function(){
   var msgerrT1T2 = "";
