   if(csGlobals.Data().CheckBox2.rawValue == 1  ) {
     var TheRow = "";
     for(i = 1; i<csGlobals.Data().TableFD._Row1.count; i++){
         TheRow = csGlobals.Data().TableFD.Row1.all.item(i);
         totalT1 += (TheRow.Cell7.rawValue ==null) ?  0 : TheRow.Cell7.rawValue ;

     }
     totalT1 = totalT1.toFixed(2);  
   } else { totalT1 = csGlobals.Data().Subform423.sumRamasaFD.rawValue ; totalT1 = totalT1.toFixed(2);  }  // total Table1



	  var totalT2 = 0;  // total Table2 
	  for(i = 1; i<csGlobals.Data().TableANG._Row1.count; i++){      
         TheRowA = csGlobals.Data().TableANG.Row1.all.item(i);      
         totalT2 += ((TheRowA.Cell1.rawValue ==null) ?  0 : TheRowA.Cell1.rawValue) +   
		                                             ((TheRowA.Cell2.rawValue ==null) ?  0 : TheRowA.Cell2.rawValue) +
