													 ((TheRowA.Cell4.rawValue ==null) ?  0 : TheRowA.Cell4.rawValue) +
													 ((TheRowA.Cell5.rawValue ==null) ?  0 : TheRowA.Cell5.rawValue) +
													 ((TheRowA.Cell6.rawValue ==null) ?  0 : TheRowA.Cell6.rawValue) ;

     }
     totalT2 = totalT2.toFixed(2);


  if(!(totalT1 == totalT2)) { msgerrT1T2 += "Totaluri inegale pentru tabel 4/5   " + totalT1  + " / " + totalT2  + "\r\n" ;  }
  //xfa.host.messageBox(msgerrT1T2); 
  return msgerrT1T2;
}


FData.validSursa = function(ASursa){
    var gasitSursa = false;
    for(i = 0;i<FData.NomenValue_Sursa.length;i++){
        if(ASursa == FData.NomenValue_Sursa[i][0]) {gasitSursa = true; break; } 
    }

    return gasitSursa;
}


FData.validProgram = function(AProgram){
    var gasitProgram = false;
    for(i = 0;i<FData.NomenValue_PrgBug.length;i++){
        if(AProgram == FData.NomenValue_PrgBug[i][0]) {gasitProgram = true; break; } 
    }

    return gasitProgram;
}

FData.validProgramSector = function(AProgram, ASector){
    var gasitProgram = false;
    for(i = 0;i<FData.NomenValue_PrgBug.length;i++){
        if((AProgram == FData.NomenValue_PrgBug[i][0]) && (ASector == FData.NomenValue_PrgBug[i][3])) {gasitProgram = true; break; } 
    }
    return gasitProgram;
}

