               TheInstanceSubformInf.SubformBeneficiar.SubformBen1.BancaBeneficiar.rawValue = banca_beneficiar;
               TheInstanceSubformInf.SubformBeneficiar.SubformBen1.InfPvPlata.rawValue = inf_pv_plata;
