    this.__GetAttributeValue =  this.__GetAttributeValue?this.__GetAttributeValue:function(AnXml, AnAttribute, ADefault){
      var TheAttributeLength = AnAttribute.length + 2;
      var TheValueStart = AnXml.indexOf(AnAttribute + "='", 0);
      if(TheValueStart == -1){
        return ADefault;
      }
      TheValueStart = TheValueStart + TheAttributeLength;
      var TheValueEnd = AnXml.indexOf("'", TheValueStart);
      return AnXml.substr(TheValueStart, TheValueEnd - TheValueStart);
    };


    this.__LoadOP= this.__LoadOP?this.__LoadOP:function(){
      this.__DoLoadOP= this.__DoLoadOP?this.__DoLoadOP:function(){
        this.__CurrentOPIndexMax = this.Xml.indexOf('<rand_op', this.__CurrentOPIndex + 1);
        var TheMax = this.__CurrentOPIndexMax;
        //xfa.host.messageBox("TheMax   " + TheMax);
        //xfa.host.messageBox("__LoadOP   " );
        //xfa.host.messageBox("this.__CurrentOPIndexMax this.__CurrentOPIndex " + this.__CurrentOPIndexMax + "   " +  this.__CurrentOPIndex  );
        if(TheMax == -1) {
          TheMax = this.Xml.length;
          //xfa.host.messageBox("TheMax = -1    " + TheMax);
        }
        this.__CurrentOPXml = this.Xml.substr(this.__CurrentOPIndex, TheMax - this.__CurrentOPIndex);
        this.__incarc_randOP(this.__CurrentOPXml);
        //xfa.host.messageBox("this.__CurrentOPXml  "  +  this.__CurrentOPXml  )   ;     
        this.__CurrentOPIndex = this.__CurrentOPIndexMax;      
        //xfa.host.messageBox("this.__CurrentOPIndex  " + this.__CurrentOPIndex);
      };
      this.__incarc_randOP = this.__incarc_randOP?this.__incarc_randOP:function(ArandOPStr){      
           //xfa.host.messageBox("__incarc_randOP " + ArandOPStr);
           this.__randOP = new Object();
           this.__randOP.NrOp =  this.__GetAttributeValue(ArandOPStr, "nr_op", '').replace(/^\s+|\s+$/gm,''); 

           var xml_nr_op = this.__GetAttributeValue(ArandOPStr, "nr_op", '').replace(/^\s+|\s+$/gm,''); 
           if(xml_nr_op.length>10){this.__MsgErrImpXml += xml_nr_op + " Lungimea NUMAR OP " + xml_nr_op.length + " permisa 10 " + " " + xml_nr_op + " \r\n"; }

           //xfa.host.messageBox("this.__randOP.NrOP " + this.__randOP.NrOP);
           this.__randOP.IbanPlatitor =  this.__GetAttributeValue(ArandOPStr, "iban_platitor", '').toUpperCase().replace(/^\s+|\s+$/gm,''); 

           //this.__randOP.DenTrezorerie =   this.__exista_diacriticXml(this.__GetAttributeValue(ArandOPStr, "den_trezorerie", '')); 

           // se preia bicul si se cauta in nomenclator, pentru a prelua denumirea unitatii bancare         
            var TheResultBCxml = csGlobals.Data().cautBICBanca(this.__randOP.IbanPlatitor);
			//xfa.host.messageBox("iban_pl::exit codbanca " + TheResultBCxml.codbanca);
			//xfa.host.messageBox("iban_pl::exit denumiredbanca " + TheResultBCxml.denbanca);
            //this.__randOP.DenTrezorerie =   this.__GetAttributeValue(ArandOPStr, "den_trezorerie", ''); 
            this.__randOP.DenTrezorerie =   TheResultBCxml.denbanca.replace(/^\s+|\s+$/gm,'');
           //xfa.host.messageBox(" __incarc_randOP");
           this.__randOP.CodProgram =  this.__GetAttributeValue(ArandOPStr, "cod_program", '').toUpperCase().replace(/^\s+|\s+$/gm,'');

           var xml_cod_program = this.__GetAttributeValue(ArandOPStr, "cod_program", '').toUpperCase().replace(/^\s+|\s+$/gm,'');
           if(xml_cod_program.length>10){this.__MsgErrImpXml += "NUMAR OP " + xml_nr_op + " Lungimea COD PROGRAM " + xml_cod_program.length + " permisa 10 " + " " + xml_cod_program + " \r\n"; }

           //xfa.host.messageBox(" __incarc_randOP dupa cp");
           this.__randOP.CodAngajament =  this.__GetAttributeValue(ArandOPStr, "cod_angajament", '').toUpperCase().replace(/^\s+|\s+$/gm,'');            

           var xml_cod_angajament = this.__GetAttributeValue(ArandOPStr, "cod_angajament", '').toUpperCase().replace(/^\s+|\s+$/gm,'');            
           if(xml_cod_angajament.length>11){this.__MsgErrImpXml += "NUMAR OP " + xml_nr_op + " Lungimea COD ANGAJAMENT " + xml_cod_angajament.length + " permisa 11 " + " " + xml_cod_angajament + " \r\n"; }

           this.__randOP.IndAngajament =  this.__GetAttributeValue(ArandOPStr, "ind_angajament", '').toUpperCase().replace(/^\s+|\s+$/gm,'');            

           var xml_ind_angajament = this.__GetAttributeValue(ArandOPStr, "ind_angajament", '').toUpperCase().replace(/^\s+|\s+$/gm,'');            
           if(xml_ind_angajament.length>3){this.__MsgErrImpXml += "NUMAR OP " + xml_nr_op + " Lungimea INDICATOR ANGAJAMENT " + xml_ind_angajament.length + " permisa 3 " + " " + xml_ind_angajament + " \r\n"; }                                 
           //this.__randOP.DenTrezorerie =   this.__GetAttributeValue(ArandOPStr, "den_trezorerie", ''); 


           this.__randOP.CifBeneficiar =  this.__GetAttributeValue(ArandOPStr, "cui_beneficiar", '').replace(/^\s+|\s+$/gm,''); 
           //this.__randOP.DenBeneficiar =   this.__exista_diacriticXml(this.__GetAttributeValue(ArandOPStr, "den_beneficiar", '')); 
           this.__randOP.DenBeneficiar =   this.__GetAttributeValue(ArandOPStr, "den_beneficiar", '').replace(/^\s+|\s+$/gm,''); 

           var xml_den_beneficiar = this.__GetAttributeValue(ArandOPStr, "den_beneficiar", '').replace(/^\s+|\s+$/gm,'');    
           if(xml_den_beneficiar.length>30){this.__MsgErrImpXml += "NUMAR OP " + xml_nr_op + " Lungimea DENUMIRE BENEFICIAR " + xml_den_beneficiar.length + " permisa 30 " + " " + xml_den_beneficiar + " \r\n"; }                                 


           this.__randOP.IbanBeneficiar =  this.__GetAttributeValue(ArandOPStr, "iban_beneficiar", '').toUpperCase().replace(/^\s+|\s+$/gm,'');            
           //this.__randOP.DenBancaTrez =   this.__exista_diacriticXml(this.__GetAttributeValue(ArandOPStr, "den_banca_trez", ''));
           TheResultBCxml = csGlobals.Data().cautBICBanca(this.__randOP.IbanBeneficiar.replace(/^\s+|\s+$/gm,''));           
           //this.__randOP.DenBancaTrez =   this.__GetAttributeValue(ArandOPStr, "den_banca_trez", '');                        
           this.__randOP.DenBancaTrez =    TheResultBCxml.denbanca.replace(/^\s+|\s+$/gm,'');
           this.__randOP.SumaOp =  this.__GetAttributeValue(ArandOPStr, "suma_op", '').replace(/^\s+|\s+$/gm,'');            
           this.__randOP.NrEvidPlatii =  this.__GetAttributeValue(ArandOPStr, "nrevidpl", '').replace(/^\s+|\s+$/gm,'');                                             
           //this.__randOP.Explicatii =   this.__exista_diacriticXml(this.__GetAttributeValue(ArandOPStr, "explicatii", ''));
           this.__randOP.Explicatii =   this.__GetAttributeValue(ArandOPStr, "explicatii", '').replace(/^\s+|\s+$/gm,'');
           var xml_explicatii = this.__GetAttributeValue(ArandOPStr, "explicatii", '').replace(/^\s+|\s+$/gm,'');   
           if(xml_explicatii.length>70){this.__MsgErrImpXml += "NUMAR OP " + xml_nr_op + " Lungimea REPREZENTIND " + xml_explicatii.length + " permisa 70 " + " " + xml_explicatii + " \r\n"; }                                 

           this.__insert_randOP(this.__randOP); ;      
      };



