  TheMethods.__GenerateXml = function(){
    this.__DoGenerateXml = this.__DoGenerateXml?this.__DoGenerateXml:function(){
      //this.Data.SumaControl.rawValue = this.GetControlSum();
      var TheXml = '<?xml version=\"1.0\"?><' + this.Declaratie.Numar;
      //xfa.host.messageBox("1 TheXml " + TheXml);
      TheXml += ' xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"';
      TheXml += ' xsi:schemaLocation=\"mfp:anaf:dgti:' + this.Declaratie.Numar + ':declaratie:v1\"';
      TheXml += ' xmlns=\"mfp:anaf:dgti:' + this.Declaratie.Numar + ':declaratie:v1\"';
      //xfa.host.messageBox("11 TheXml " + TheXml);
      //xfa.host.messageBox(TheXml);
      TheXml += this.__GenerateXmlForHeader();
      TheXml += '>';
      //xfa.host.messageBox(TheXml);
      TheXml += this.__GenerateXmlSectA();
      TheXml += this.__GenerateXmlSectB();
      //TheXml += this.__GenerateXmlForORDNT();
      TheXml += '<\/' + this.Declaratie.Numar + '>';
      //xfa.host.messageBox("12 TheXml " + TheXml);

      this.Form.removeDataObject("Erori si Avertizari.txt");
      this.Form.removeDataObject('' + this.Declaratie.Numar + '.xml');
      //xfa.host.messageBox("13 ");
      this.Form.createDataObject('' + this.Declaratie.Numar + '.xml', TheXml);
      //xfa.host.messageBox("14 ");
    };

    this.__Escape = this.__Escape?this.__Escape:function(AString){
      AString = (AString==null)? "" : AString; 
      var TheText = "";
      TheText = AString.replace(/["]/g,"&quot;");
      TheText = TheText.replace(/[<]/g,"&lt;");
      TheText = TheText.replace(/[>]/g,"&gt;");
      TheText = TheText.replace(/[&]/g,"&amp;");
      TheText = TheText.replace(/[']/g,"&apos;");
      return TheText;
    };

    this.__FormatDate = this.__FormatDate?this.__FormatDate:function(AString){
      //data in format zz.ll.aaaa - transf din aaaa-ll-zz
      //dar poate primi si data sub forma deja data zz.ll.aaaa
      if(AString.substring(2,3)!="."){
        return this.__Escape(AString.substring(8, 10) + "." + AString.substring(5, 7) + "." + AString.substring(0, 4));
      }
      return this.__Escape(AString);
    };

