            TheXml += " ckbx_ang_leg_emise_ct_an_urm=\"" + this.Data.SubformSectiuneaA.CheckBox13.rawValue  + "\"";         
            TheXml += '>';
               TheT2Row1count =  this.Data.SubformSectiuneaA.Table2._Row1.count ;
			   //xfa.host.messageBox("TheT2Row1count " + TheT2Row1count);
               if(TheT2Row1count>1) {
                    for(it2=1; it2<TheT2Row1count;it2++ ) {
				       var TheRowT2 =  this.Data.SubformSectiuneaA.Table2.Row1.all.item(it2);
