                       TheXml += " program=\"" + TheRowT2.Cell7.rawValue  + "\"";         
                       TheXml += " codSSI=\"" + TheRowT2.Cell8.rawValue  + "\"";         

                       TheXml += '/>';
                    }   
			   } 
            TheXml += '<\/' +   'ang_legale_plati>';
            TheXml += '<\/' +   'sectiuneaA>';


      return TheXml;
  };

 this.__GenerateXmlSectB = this.__GenerateXmlSectB?this.__GenerateXmlSectB:function(){
