    this.__GenerateXmlForHeader = this.__GenerateXmlForHeader?this.__GenerateXmlForHeader:function(){
      //xfa.host.messageBox("GenerateXmlForHeader in");
      var TheXml = ' DenInstPb=\"' + this.__Escape(this.Data.SubformAntet.DenInstPb.rawValue) + '\"'; 
      TheXml += ' Cif=\"' + this.__Escape(this.Data.SubformAntet.cif.rawValue.replace(/^\s+|\s+$/gm,'')) + '\"';
      TheXml += ' SubtitluDF=\"' + this.__Escape(this.Data.SubformAntet.SubtitluDF.rawValue.replace(/^\s+|\s+$/gm,'')) + '\"';

      //TheXml += ' NrUnicInreg=\"' + this.__Escape(this.Data.SubformAntet.NrUnicInreg.rawValue.replace(/^\s+|\s+$/gm,''))+ '\"';
      TheXml += ' NrUnicInreg=\"' + ( (this.Data.SubformAntet.NrUnicInreg.rawValue == null)?  "" :   this.__Escape(this.Data.SubformAntet.NrUnicInreg.rawValue.replace(/^\s+|\s+$/gm,'')) ) + '\"';

      TheXml += ' Revizuirea=\"' + this.__Escape(this.Data.SubformAntet.Revizuirea.rawValue.replace(/^\s+|\s+$/gm,''))+ '\"';

	  TheXml += ' DataRevizuirii=\"' + this.__FormatDate(this.Data.SubformAntet.DataRevizuirii.rawValue)+ '\"';
	   //xfa.host.messageBox("GenerateXmlForHeader out");


       return TheXml;
